window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-85b69b08cf291378"]={"versions": [{"id": "FIG-85b69b08cf291378", "releases": ["R2.1.20", "R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Metamodell- und Paketdiagramm zur Veranschaulichung der methodischen Einordnung des AUTOSAR-Template-Modells innerhalb der OMG-Metamodell-Hierarchie (MOF / UML 2.0). Das Diagramm stellt dar, wie das AUTOSAR-Metamodell als UML-Profil auf UML 2.0 aufsetzt und über welche Standardbeziehungen die Metamodellierungsebenen verknüpft sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Pakete bzw. Profil-Entitäten sowie zwei gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li>Paket <code>MOF 2.0</code>: Repräsentiert die Meta-Metamodellebene (M3 nach OMG).\n</li><li>Paket <code>UML 2.0</code>: Repräsentiert das UML-Metamodell (M2-Ebene), das über eine gestrichelte gerichtete Beziehung mit offenem Pfeil und dem Stereotyp <code>«instanceOf»</code> instanziell auf <code>MOF 2.0</code> zurückgeführt ist.\n</li><li>Profil-Paket <code>«profile» AUTOSAR Template Profile</code> (im Tab-Kopf bezeichnet als <code>AUTOSARTemplateProfile</code> unter <code>«profile»</code>): Repräsentiert das AUTOSAR-spezifische Metamodell bzw. Schablonen-Profil, welches über eine gestrichelte Import-Abhängigkeit mit offenem Pfeil und Stereotyp <code>«import»</code> das Basispaket <code>UML 2.0</code> importiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodellierungsdiagramm ohne Laufzeitverhalten, Zustandsübergänge oder Nachrichtensequenzen. Die dargestellten Beziehungen definieren compile- bzw. modellierungszeitige Abhängigkeiten: <code>AUTOSARTemplateProfile</code> importiert die Metaklassen von <code>UML 2.0</code>, welches seinerseits eine Instanz der Meta-Metamodell-Spezifikation <code>MOF 2.0</code> darstellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Modellierungs- und AUTOSAR-Tooling-Entwickler: Das AUTOSAR-Template-Modell wird formal nicht als eigenständiges MOF-basiertes Metamodell (First-Class Metamodel) definiert, sondern als UML-2.0-Profil realisiert. Modellierungs- und Codegenerierungswerkzeuge müssen Stereotype, Tagged Values und OCL-Constraints des <code>AUTOSARTemplateProfile</code> auf Basis des standardisierten <code>UML 2.0</code>-Metamodells interpretieren und auflösen können.</p>"}, {"id": "FIG-83ef4e51c9b269ec", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Metamodell- und Paketdiagramm zur Veranschaulichung der methodischen Einordnung des AUTOSAR-Template-Modells innerhalb der OMG-Metamodell-Hierarchie (MOF / UML 2.0). Das Diagramm stellt dar, wie das AUTOSAR-Metamodell als UML-Profil auf UML 2.0 aufsetzt und über welche Standardbeziehungen die Metamodellierungsebenen verknüpft sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Pakete bzw. Profil-Entitäten sowie zwei gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li>Paket <code>MOF 2.0</code>: Repräsentiert die Meta-Metamodellebene (M3 nach OMG).\n</li><li>Paket <code>UML 2.0</code>: Repräsentiert das UML-Metamodell (M2-Ebene), das über eine gestrichelte gerichtete Beziehung mit offenem Pfeil und dem Stereotyp <code>«instanceOf»</code> instanziell auf <code>MOF 2.0</code> zurückgeführt ist.\n</li><li>Profil-Paket <code>«profile» AUTOSAR Template Profile</code> (im Tab-Kopf bezeichnet als <code>AUTOSARTemplateProfile</code> unter <code>«profile»</code>): Repräsentiert das AUTOSAR-spezifische Metamodell bzw. Schablonen-Profil, welches über eine gestrichelte Import-Abhängigkeit mit offenem Pfeil und Stereotyp <code>«import»</code> das Basispaket <code>UML 2.0</code> importiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodellierungsdiagramm ohne Laufzeitverhalten, Zustandsübergänge oder Nachrichtensequenzen. Die dargestellten Beziehungen definieren compile- bzw. modellierungszeitige Abhängigkeiten: <code>AUTOSARTemplateProfile</code> importiert die Metaklassen von <code>UML 2.0</code>, welches seinerseits eine Instanz der Meta-Metamodell-Spezifikation <code>MOF 2.0</code> darstellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Modellierungs- und AUTOSAR-Tooling-Entwickler: Das AUTOSAR-Template-Modell wird formal nicht als eigenständiges MOF-basiertes Metamodell (First-Class Metamodel) definiert, sondern als UML-2.0-Profil realisiert. Modellierungs- und Codegenerierungswerkzeuge müssen Stereotype, Tagged Values und OCL-Constraints des <code>AUTOSARTemplateProfile</code> auf Basis des standardisierten <code>UML 2.0</code>-Metamodells interpretieren und auflösen können.</p>"}, {"id": "FIG-728b8504a5a69b7a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Metamodell- und Paketdiagramm zur Veranschaulichung der methodischen Einordnung des AUTOSAR-Template-Modells innerhalb der OMG-Metamodell-Hierarchie (MOF / UML 2.0). Das Diagramm stellt dar, wie das AUTOSAR-Metamodell als UML-Profil auf UML 2.0 aufsetzt und über welche Standardbeziehungen die Metamodellierungsebenen verknüpft sind.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Pakete bzw. Profil-Entitäten sowie zwei gerichtete Abhängigkeitsbeziehungen:</p>\n<ul class=\"fig-list\"><li>Paket <code>MOF 2.0</code>: Repräsentiert die Meta-Metamodellebene (M3 nach OMG).\n</li><li>Paket <code>UML 2.0</code>: Repräsentiert das UML-Metamodell (M2-Ebene), das über eine gestrichelte gerichtete Beziehung mit offenem Pfeil und dem Stereotyp <code>«instanceOf»</code> instanziell auf <code>MOF 2.0</code> zurückgeführt ist.\n</li><li>Profil-Paket <code>«profile» AUTOSAR Template Profile</code> (im Tab-Kopf bezeichnet als <code>AUTOSARTemplateProfile</code> unter <code>«profile»</code>): Repräsentiert das AUTOSAR-spezifische Metamodell bzw. Schablonen-Profil, welches über eine gestrichelte Import-Abhängigkeit mit offenem Pfeil und Stereotyp <code>«import»</code> das Basispaket <code>UML 2.0</code> importiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodellierungsdiagramm ohne Laufzeitverhalten, Zustandsübergänge oder Nachrichtensequenzen. Die dargestellten Beziehungen definieren compile- bzw. modellierungszeitige Abhängigkeiten: <code>AUTOSARTemplateProfile</code> importiert die Metaklassen von <code>UML 2.0</code>, welches seinerseits eine Instanz der Meta-Metamodell-Spezifikation <code>MOF 2.0</code> darstellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Modellierungs- und AUTOSAR-Tooling-Entwickler: Das AUTOSAR-Template-Modell wird formal nicht als eigenständiges MOF-basiertes Metamodell (First-Class Metamodel) definiert, sondern als UML-2.0-Profil realisiert. Modellierungs- und Codegenerierungswerkzeuge müssen Stereotype, Tagged Values und OCL-Constraints des <code>AUTOSARTemplateProfile</code> auf Basis des standardisierten <code>UML 2.0</code>-Metamodells interpretieren und auflösen können.</p>"}], "trans": [{"from": "FIG-85b69b08cf291378", "to": "FIG-83ef4e51c9b269ec", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-83ef4e51c9b269ec", "to": "FIG-728b8504a5a69b7a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
